def parse_range(header, size):
    """
    Parses an HTTP Range header for a resource of the given size.
    Returns a list of (start, end) inclusive byte offsets, or None if the header
    is unsatisfiable or malformed.
    """
    if not header or not header.startswith('bytes='):
        return None

    ranges_str = header[6:]
    if not ranges_str:
        return None

    result = []
    unsatisfiable = True

    for part in ranges_str.split(','):
        part = part.strip()
        if not part:
            continue

        if '-' in part:
            hyphen_index = part.rfind('-')
            start_str = part[:hyphen_index]
            end_str = part[hyphen_index + 1:]

            start = None
            end = None

            if start_str:
                try:
                    start = int(start_str)
                except ValueError:
                    return None
            else:
                start = 0

            if end_str:
                try:
                    end = int(end_str)
                except ValueError:
                    return None
            else:
                end = size - 1

            # Check for unsatisfiable range: start >= size
            if start >= size:
                continue

            # Clamp end to the last byte
            if end >= size:
                end = size - 1

            # Handle suffix range (e.g., -500)
            if start == 0 and end < 0:
                # end is negative, meaning suffix length
                suffix_len = abs(end)
                if suffix_len >= size:
                    start = 0
                    end = size - 1
                else:
                    start = size - suffix_len
                    end = size - 1
            elif start == 0 and end < 0:
                # This case shouldn't happen due to the previous check, but kept for safety
                continue

            # Ensure start <= end
            if start > end:
                continue

            result.append((start, end))
            unsatisfiable = False
        else:
            return None

    if not result:
        return None

    return result
```

