import collections

class LFUCache:

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.min_freq = 0
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = collections.defaultdict(collections.OrderedDict)

    def get(self, key: int) -> int:
        if key not in self.key_to_val:
            return -1

        # Update frequency
        freq = self.key_to_freq[key]
        self.key_to_freq[key] = freq + 1

        # Move key to new frequency bucket
        del self.freq_to_keys[freq][key]
        self.freq_to_keys[freq + 1][key] = None

        # Update min_freq if necessary
        if not self.freq_to_keys[freq]:
            if freq == self.min_freq:
                self.min_freq += 1

        return self.key_to_val[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity <= 0:
            return

        if key in self.key_to_val:
            self.key_to_val[key] = value
            self.get(key) # Update frequency
            return

        if self.capacity == len(self.key_to_val):
            # Evict LRU from the min_freq bucket
            lru_key, _ = self.freq_to_keys[self.min_freq].popitem(last=False)
            del self.key_to_val[lru_key]
            del self.key_to_freq[lru_key]

        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        self.freq_to_keys[1][key] = None
        self.min_freq = 1
