def wildcard_match(pattern, s):
    m, n = len(pattern), len(s)
    # dp[i][j] is True if pattern[0..i-1] matches s[0..j-1]
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Initialize first row: pattern "" matches s "" only
    for j in range(1, n + 1):
        dp[0][j] = False

    # Initialize first column: pattern "" matches s "" only
    # (Already set to False for j>0, and dp[0][0] is True)

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i - 1] == s[j - 1] or pattern[i - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                # Case 1: '*' matches empty string
                dp[i][j] = dp[i - 1][j]
                # Case 2: '*' matches at least one character
                if not dp[i][j]:
                    dp[i][j] = dp[i][j - 1]
            else:
                dp[i][j] = False

    return dp[m][n]
