import re
from operator import add, sub, mul, truediv, mod, pow

def evaluate(expr):
    # Tokenize the expression
    tokens = re.findall(r"""
        \d+\.?\d*  |  # Numbers (integers and decimals)
        [+\-*/%()]  |  # Operators and parentheses
        \.\.\.      |  # Exponentiation operator
        [a-zA-Z]    |  # Variable names (not used but for completeness)
        .           # Any other character (will raise error)
    """, expr, re.VERBOSE)

    # Filter out empty strings and check for invalid characters
    tokens = [t for t in tokens if t]
    if not tokens:
        raise ValueError("Empty expression")

    # Check for invalid characters
    if any(not re.match(r"[\d+\-*/%().]|(\.\.\.)", t) for t in tokens):
        raise ValueError("Invalid character in expression")

    # Convert tokens to a list of objects: (type, value)
    # Types: 'NUM', 'OP', 'UNARY'
    processed = []
    i = 0
    n = len(tokens)

    while i < n:
        token = tokens[i]
        if re.match(r"\d+\.?\d*", token):
            # Parse number
            try:
                num = float(token) if '.' in token else int(token)
            except ValueError:
                raise ValueError(f"Invalid number: {token}")
            processed.append(('NUM', num))
        elif token in '+-*/%()':
            processed.append(('OP', token))
        elif token == '...':
            processed.append(('OP', '**'))
        elif token in ('+', '-'):
            # Check for unary operator
            if i == 0 or tokens[i-1] in '+-*/%()':
                processed.append(('UNARY', token))
            else:
                processed.append(('OP', token))
        else:
            raise ValueError(f"Unknown token: {token}")
        i += 1

    # Shunting-yard algorithm to convert to Reverse Polish Notation (RPN)
    output = []
    op_stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '**': 3}
    right_assoc = {'**': True}
    unary_prec = 4 # Higher than any binary operator

    for token_type, value in processed:
        if token_type == 'NUM':
            output.append(value)
        elif token_type == 'UNARY':
            op_stack.append((value, unary_prec, True))
        elif token_type == 'OP':
            # Handle binary operator
            while op_stack:
                top_type, top_val, top_unary = op_stack[-1]
                if top_unary:
                    break
                if (precedence.get(top_val, 0) > precedence.get(value, 0) or
                    (precedence.get(top_val, 0) == precedence.get(value, 0) and 
                     not right_assoc.get(value, False))):
                    output.append(op_stack.pop()[1])
                else:
                    break
            op_stack.append((value, precedence.get(value, 0), False))
        elif token_type == 'PAREN':
            if value == '(':
                op_stack.append((value, 0, False))
            else: # ')'
                while op_stack and op_stack[-1][0] != '(':
                    output.append(op_stack.pop()[1])
                if not op_stack:
                    raise ValueError("Mismatched parentheses")
                op_stack.pop() # Remove '('

    while op_stack:
        top_type, top_val, top_unary = op_stack.pop()
        if top_unary:
            output.append(top_val)
        elif top_val in '()':
            raise ValueError("Mismatched parentheses")
        else:
            output.append(top_val)

    # Evaluate RPN
    stack = []
    ops = {
        '+': add, '-': sub, '*': mul, '/': truediv, '%': mod, '**': pow
    }

    for token in output:
        if isinstance(token, (int, float)):
            stack.append(token)
        else:
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            a = stack.pop()
            if token == '-' and isinstance(a, (int, float)) and isinstance(b, (int, float)):
                 # Handle subtraction order
                 res = a - b
            else:
                res = ops[token](a, b)
            stack.append(res)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    result = stack[0]
    # Return int if it's a whole number
    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
