class RollbackDSU:
    def __init__(self, n):
        self.n = n
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.snapshots = []
        self.current_snapshot_index = -1

    def find(self, x):
        return self.parent[x]

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)
        if a == b:
            return False

        if self.size[a] < self.size[b]:
            a, b = b, a

        self.history.append((a, b, self.parent[b]))
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

    def snapshot(self):
        self.snapshots.append(len(self.history))
        self.current_snapshot_index += 1
        return self.current_snapshot_index

    def rollback(self, token):
        if token < 0 or token > self.current_snapshot_index:
            return

        target_len = self.snapshots[token]
        while len(self.history) > target_len:
            a, b, parent_b = self.history.pop()
            self.parent[b] = parent_b
            self.size[a] -= self.size[b]

        self.current_snapshot_index = token

    def components(self):
        unique_roots = set()
        for i in range(self.n):
            unique_roots.add(self.find(i))
        return len(unique_roots)
