import bisect
from collections import defaultdict

class WildcardTrie:
    def __init__(self):
        # Trie structure: children is a dict mapping char to node
        self.root = {}
        # Maps a pattern (string) to a sorted list of words matching it
        self.pattern_index = defaultdict(list)
        # Maps a word to its count (to handle duplicates)
        self.word_counts = defaultdict(int)
        # Maps a word to the list of patterns it matches
        self.word_to_patterns = defaultdict(list)

    def add(self, word):
        self.word_counts[word] += 1
        self._add_to_trie(word)
        return True

    def _add_to_trie(self, word):
        node = self.root
        for i, char in enumerate(word):
            if char == '.':
                # For wildcard chars, we need to store the index to backtrack
                # and the next character to match.
                # Key: (index, next_char)
                key = (i, char)
                if key not in node:
                    node[key] = {}
                node = node[key]
            else:
                if char not in node:
                    node[char] = {}
                node = node[char]

        # Mark the end of the word
        node['#'] = True

    def remove(self, word):
        if self.word_counts[word] == 0:
            return False

        self.word_counts[word] -= 1

        # Remove from pattern index
        for pattern in self.word_to_patterns[word]:
            lst = self.pattern_index[pattern]
            # Remove the first occurrence of the word
            try:
                lst.remove(word)
            except ValueError:
                pass

        # Remove from word_to_patterns
        del self.word_to_patterns[word]

        # Rebuild the trie
        self.root = {}
        for w in self.word_counts:
            self._add_to_trie(w)

        return True

    def search(self, pattern):
        results = []
