def subtract(base, cuts):
    # Combine all intervals into a single list and sort them by start time
    intervals = sorted(base + cuts, key=lambda x: x[0])
    result = []
    current_start, current_end = None, None

    for start, end in intervals:
        # If the current interval is completely before the next one, add it to result
        if current_end is None or end <= current_start:
            if current_start is not None:
                result.append([current_start, current_end])
            current_start, current_end = start, end
        else:
            # If the current interval overlaps with the next one, merge them
            current_end = max(current_end, end)

    # Add the last interval to the result
    if current_start is not None:
        result.append([current_start, current_end])

    # Initialize the result of the subtraction
    surviving_intervals = []

    # Iterate through the merged intervals to perform the subtraction
    for start, end in result:
        # If the current interval is completely before the first cut, add it to result
        if end <= 0:
            surviving_intervals.append([start, end])
        # If the current interval is completely after the last cut, add it to result
        elif start >= 0:
            surviving_intervals.append([start, end])
        else:
            # The interval overlaps with the cuts, so we need to split it
            # The part before the first cut
            if start < 0:
                surviving_intervals.append([start, 0])
            # The part after the last cut
            if end > 0:
                surviving_intervals.append([0, end])

    # Merge adjacent intervals that touch
    merged = []
    for start, end in surviving_intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    return merged
