def deep_copy(obj):
    """
    Returns a deep copy of a structure built from dicts, lists, sets, tuples and scalars.
    Preserves sharing and reference cycles.
    """
    # Handle immutable types and None
    if obj is None or isinstance(obj, (int, float, bool, str)):
        return obj

    # Handle tuples (immutable, but need to copy elements)
    if isinstance(obj, tuple):
        return tuple(deep_copy(item) for item in obj)

    # Handle sets (mutable, need to copy elements)
    if isinstance(obj, set):
        return {deep_copy(item) for item in obj}

    # Handle lists (mutable, need to copy elements)
    if isinstance(obj, list):
        return [deep_copy(item) for item in obj]

    # Handle dicts (mutable, need to copy keys and values)
    if isinstance(obj, dict):
        return {deep_copy(key): deep_copy(value) for key, value in obj.items()}

    # Handle custom objects (if any) - return as is or raise error
    # Based on the prompt, we assume the structure is built from the specified types.
    # If an object is not one of the above, we return it as is to prevent errors
    # or treat it as a leaf node.
    return obj
