def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    digits = []
    base = len(alphabet)
    while n > 0:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")
    base = len(alphabet)
    if s[0] == '-':
        sign = -1
        s = s[1:]
    else:
        sign = 1
    if not s:
        raise ValueError("Empty string")
    value = 0
    for char in s:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' not in alphabet")
        value = value * base + alphabet.index(char)
    return sign * value
