import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # Priority queue: (total_cost, num_edges, current_node, path_so_far)
    # Using num_edges as a secondary key to break ties before the path is fully reconstructed
    heap = [(0, 0, src, [src])]
    visited = set()

    while heap:
        cost, edges, u, path = heapq.heappop(heap)

        if u in visited:
            continue
        visited.add(u)

        if u == dst:
            return (cost, path)

        for v, w in graph.get(u, []):
            if v in visited:
                continue
            new_cost = cost + w
            new_edges = edges + 1
            heapq.heappush(heap, (new_cost, new_edges, v, path + [v]))

    return (None, [])
```

