import heapq

def topo_lex(graph):
    # Calculate in-degree for all nodes
    # We need to consider nodes that appear only as successors
    in_degree = {}
    for node, successors in graph.items():
        in_degree[node] = in_degree.get(node, 0)
        for succ in successors:
            in_degree[succ] = in_degree.get(succ, 0) + 1

    # Initialize heap with nodes having 0 in-degree
    # We use a list of tuples (node, node) to ensure lexicographical order
    # when nodes have the same priority (in-degree)
    heap = []
    for node, degree in in_degree.items():
        if degree == 0:
            heapq.heappush(heap, (node, node))

    topo_order = []
    visited_count = 0

    while heap:
        # Pop the smallest node
        current_node, _ = heapq.heappop(heap)
        topo_order.append(current_node)
        visited_count += 1

        # Update in-degrees of successors
        if current_node in graph:
            for neighbor in graph[current_node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    heapq.heappush(heap, (neighbor, neighbor))

    if visited_count != len(in_degree):
        return None

    return topo_order
