module.exports = class Emitter {
  constructor() {
    this._events = {};
  }

  on(event, fn) {
    if (!this._events[event]) {
      this._events[event] = [];
    }
    this._events[event].push(fn);
    return () => this.off(event, fn);
  }

  once(event, fn) {
    const onceFn = (...args) => {
      this.off(event, onceFn);
      fn(...args);
    };
    this.on(event, onceFn);
    return () => this.off(event, onceFn);
  }

  off(event, fn) {
    if (!this._events[event]) return;
    this._events[event] = this._events[event].filter(listener => listener !== fn);
  }

  emit(event, ...args) {
    const listeners = this._events[event] || [];
    const listenersToRun = listeners.slice();
    let error = null;

    for (const listener of listenersToRun) {
      try {
        listener(...args);
      } catch (err) {
        if (!error) error = err;
      }
    }

    if (error) throw error;
    return listenersToRun.length;
  }
};
