      } else if (typeof value === 'object' && value !== null && value.text !== undefined) {
        const subResult = value;
        result.text += subResult.text;
        result.values.push(...subResult.values);
      } else {
        const placeholderIndex = result.values.length + 1;
        result.text += `$${placeholderIndex}`;
        result.values.push(value);
      }
    }
  }

  return result;
