module.exports = function chunkAsync(source, size) {
  if (size <= 0) {
    throw new Error('Chunk size must be greater than 0');
  }

  return (async function* () {
    const iterator = source[Symbol.asyncIterator] ? source[Symbol.asyncIterator]() : source[Symbol.iterator]();
    const buffer = [];
    let done = false;

    try {
      while (!done) {
        // Fill buffer up to size, but stop if we hit the end
        while (buffer.length < size) {
          const { value, done: iterDone } = await iterator.next();
          if (iterDone) {
            done = true;
            break;
          }
          buffer.push(value);
        }

        // Yield the current chunk
        if (buffer.length > 0) {
          yield buffer.splice(0, size);
        } else if (done) {
          break;
        }
      }
    } finally {
      // Ensure the iterator is closed if the consumer stops early
      if (!done) {
        await iterator.return?.();
      }
    }
  })();
};
