module.exports = function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) {
    return function* () {};
  }

  const iterators = iterables.map(iter => iter[Symbol.iterator]());

  return function* () {
    while (true) {
      const row = [];
      let allDone = true;

      for (let i = 0; i < iterators.length; i++) {
        const iterator = iterators[i];
        const { value, done } = iterator.next();

        if (done) {
          row.push(fill);
          allDone = true;
        } else {
          row.push(value);
          allDone = false;
        }
      }

      if (allDone) {
        break;
      }

      yield row;
    }
  };
};
