    const len = pairs.length;

    for (let i = 0; i < len; i++) {
      const pair = pairs[i];
      const eqIndex = pair.indexOf('=');
      let key, value;

      if (eqIndex === -1) {
        key = pair;
        value = '';
      } else {
        key = pair.slice(0, eqIndex);
        value = pair.slice(eqIndex + 1);
      }

      key = decodeURIComponent(key.replace(/\+/g, ' '));
      value = decodeURIComponent(value.replace(/\+/g, ' '));

      const parts = key.match(/^(.+?)\[(.+?)\]$/);
      if (parts) {
        const base = parts[1];
        const sub = parts[2];
        if (!result[base]) {
          result[base] = {};
        }
        if (sub === '') {
          result[base].push(value);
        } else {
          if (typeof result[base][sub] === 'undefined') {
            result[base][sub] = value;
          } else {
            const existing = result[base][sub];
            if (Array.isArray(existing)) {
              existing.push(value);
            } else {
              result[base][sub] = [existing, value];
            }
          }
        }
      } else {
        if (result[key] !== undefined) {
          const existing = result[key];
          if (Array.isArray(existing)) {
            existing.push(value);
          } else {
