module.exports = function toposortTasks(tasks) {
  const visited = new Set();
  const visiting = new Set();
  const result = new Map();
  const errors = new Map();
  const running = new Map();

  const getDependencies = (name) => tasks[name].deps || [];

  const checkCycle = (name) => {
    if (visiting.has(name)) {
      throw new Error(`cycle involving ${name}`);
    }
    if (visited.has(name)) {
      return;
    }
    visiting.add(name);
    for (const dep of getDependencies(name)) {
      if (!tasks[dep]) {
        throw new Error(`missing dependency ${dep}`);
      }
      checkCycle(dep);
    }
    visiting.delete(name);
    visited.add(name);
  };

  const runTask = async (name) => {
    if (errors.has(name)) {
      return;
    }
    if (running.has(name)) {
      return running.get(name);
    }
    if (visited.has(name)) {
      return result.get(name);
    }

    visiting.add(name);
    try {
      const deps = {};
      for (const dep of getDependencies(name)) {
        if (errors.has(dep)) {
          throw errors.get(dep);
        }
        await runTask(dep);
        deps[dep] = result.get(dep);
      }
      const value = await tasks[name].run(deps);
      result.set(name, value);
      return value;
    } catch (err) {
      errors.set(name, err);
      throw err;
    } finally {
      visiting.delete(name);
    }
  };

  const promises = [];
  for (const name of Object.keys(tasks)) {
    try {
      checkCycle(name);
    } catch (err) {
      return Promise.reject(err);
    }
    promises.push(runTask(name));
  }

  return Promise.allSettled(promises).then((settled) => {
    const rejected = settled.find((s) => s.status === 'rejected');
    if (rejected) {
      return Promise.reject(rejected.reason);
    }
    return new Map(result);
  });
};
