export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    const awaited = await value;
    return deepAwait(awaited) as Promise<DeepAwaited<T>>;
  }
  if (Array.isArray(value)) {
    return (await Promise.all(value.map(deepAwait))) as Promise<DeepAwaited<T>>;
  }
  if (typeof value === 'object' && value !== null) {
    const result: any = {};
    for (const key in value) {
      if (Object.prototype.hasOwnProperty.call(value, key)) {
        result[key] = await deepAwait(value[key]);
      }
    }
    return result as Promise<DeepAwaited<T>>;
  }
  return value as Promise<DeepAwaited<T>>;
