export type Result<T, E> = { _tag: 'ok'; value: T } | { _tag: 'err'; error: E };

export function ok<T, E>(value: T): Result<T, E> {
  return { _tag: 'ok', value };
}

export function err<T, E>(error: E): Result<T, E> {
  return { _tag: 'err', error };
}

export function isOk<T, E>(r: Result<T, E>): r is { _tag: 'ok'; value: T } {
  return r._tag === 'ok';
}

export function isErr<T, E>(r: Result<T, E>): r is { _tag: 'err'; error: E } {
  return r._tag === 'err';
}

export function map<T, E, U>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (isOk(r)) {
    return ok(fn(r.value));
  } else {
    return r;
  }
}

export function unwrapOr<T, E>(r: Result<T, E>, defaultValue: T): T {
  if (isOk(r)) {
    return r.value;
  } else {
    return defaultValue;
  }
}
