export function defineRoutes<T extends Record<string, string>>(routes: T): {
  [K in keyof T]: (params?: Record<string, string>) => string
} {
  return Object.fromEntries(
    Object.entries(routes).map(([name, template]) => {
      const paramNames = Array.from(template.matchAll(/:([a-zA-Z0-9_]+)/g)).map((m) => m[1]);
      const paramKeys = paramNames as (keyof Record<string, string>)[];

      const handler = (params?: Record<string, string>): string => {
        if (params) {
          const paramEntries = Object.entries(params);
          const paramKeysEntries = paramKeys.map((k) => [k, k] as [string, string]);

          if (paramEntries.length !== paramKeys.length) {
            const providedKeys = paramEntries.map(([k]) => k);
            const missingKeys = paramKeys.filter((k) => !providedKeys.includes(k));
            const extraKeys = providedKeys.filter((k) => !paramKeys.includes(k));

            if (missingKeys.length > 0) {
              throw new Error(`Missing required params: ${missingKeys.join(', ')}`);
            }
            if (extraKeys.length > 0) {
              throw new Error(`Extra params provided: ${extraKeys.join(', ')}`);
            }
          }
        }

        let result = template;
        for (const [key, value] of Object.entries(params ?? {})) {
          result = result.replace(new RegExp(`:${key}`, 'g'), value);
        }
        return result;
      };

      return [name, handler];
    })
  ) as any;
}
